import { Activity, AlertTriangle, Bell, Boxes, BrainCircuit, Check, ChevronRight, ClipboardList, Command, Crosshair, Database, Fuel, Gauge, HeartPulse, LayoutDashboard, LogOut, Menu, Network, Package, Plane, Plus, Radio, Search, Settings, ShieldAlert, Snowflake, Sparkles, Target, Truck, Users, X } from 'lucide-react'
