type MissionStatus = 'Active' | 'Standby' | 'Completed'
type RiskLevel = 'Low' | 'Medium' | 'High' | 'Critical'
type CargoStatus = 'In Transit' | 'Delivered' | 'Delayed'
type SearchCategory = 'All' | 'Missions' | 'Cargo' | 'Threats' | 'Alerts' | 'Expeditions'

type Mission = { id: string; name: string; destination: string; location: string; commander: string; team: number; status: MissionStatus; progress: number; eta: string; cargo: string[]; risk: RiskLevel; start: string; end: string; description: string; timeline: string[] }
type CargoRecord = { id: string; description: string; route: string; destination: string; missionId: string; status: CargoStatus; eta: string; progress: number; priority: string; risk: RiskLevel; history: string[] }
type SearchRecord = { id: string; title: string; subtitle: string; category: SearchCategory }

